}
.card {
  width: min(32rem, calc(100% - 1.5rem)); max-height: 92dvh; overflow-y: auto;
  padding: .7rem 1rem 1rem;
  background: var(--bg); border-radius: .9rem;
}
.iconbar {
  display: flex; align-items: center; flex-wrap: wrap; gap: .15rem;
  padding-bottom: .5rem; margin-bottom: .5rem; border-bottom: 1px solid var(--line);
}
.iconbar .spacer { flex: 1; }
/* The toggle row, under start and end: `24h` alone on an event, with stage, important and the
   estimate on a task. */
.flags { padding: .5rem 0 .2rem; margin: 0; border: 0; }
.flags .ib { position: relative; }
/* Stage and the estimate show their value as a badge on the icon's corner. Important has
   nothing to put in one and lights instead, the way `24h` does. */
.badge {
  position: absolute; right: .25rem; bottom: .25rem;
  min-width: .95rem; padding: 0 .1rem;
  font-size: .58rem; font-weight: 700; line-height: .95rem; text-align: center;
  color: var(--bg); background: var(--fg); border-radius: 999px;
}
.badge:empty { min-width: .55rem; height: .55rem; line-height: .55rem; }
.badge.wide { min-width: 1.15rem; }
.title-in { font-size: 1.1rem; font-weight: 600; padding: .65rem .6rem; }
.card label { margin: .7rem 0 0; }
.card small { display: block; margin-top: .25rem; font-size: .7rem; color: var(--muted); }
.row2 { display: flex; gap: .6rem; }
.row2 label { flex: 1; }
.row2 label.t { flex: 0 0 8rem; }
select {
  display: block; width: 100%; margin-top: .3rem; padding: .7rem; font: inherit;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
}
.btngroup { display: flex; margin: .7rem 0 0; }
.seg {
  flex: 1; width: auto; margin: 0; padding: .55rem .4rem; font-size: .85rem; font-weight: 500;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: 0;
}
.seg:first-child { border-radius: .5rem 0 0 .5rem; }
.seg:last-child { border-radius: 0 .5rem .5rem 0; border-left: 0; }
.seg[aria-pressed="true"] { color: var(--bg); background: var(--accent); border-color: var(--accent); }
.scope { margin-top: .7rem; }
.scope-note { font-size: .75rem; color: var(--muted); }
.body-in {
  display: block; width: 100%; margin-top: .3rem; padding: .7rem;
  font: .85rem/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
  resize: vertical;
}
/* Every field is a row: its icon, its name, and its value once it is set. The row is the pen, so
   it carries no button of its own, and a set row is plain - being above the unset ones and
   showing a value is what says it is set. */
.frows { margin-top: .4rem; }
.frow {
  display: flex; align-items: center; gap: .6rem; width: 100%; margin: 0;
  padding: .6rem .3rem; font: inherit; font-size: .9rem; text-align: left;
  color: var(--fg); background: none;
  border: 0; border-top: 1px solid var(--line); border-radius: 0; cursor: pointer;
